def decrease_if_enough(self, row_id: int, column: str, amount: int) -> bool:
    """`UPDATE ... SET col = col - n WHERE id = ? AND col >= n`와 같다. 영향 행이 있으면 True."""
    with self._lock:
        row = self.rows.get(row_id)
        if row is None or row[column] < amount:
            return False
        row[column] -= amount
        return True

def increase(self, row_id: int, column: str, amount: int) -> None:
    with self._lock:
        self.rows[row_id][column] += amount

