class PgClient:
    def __init__(
        self,
        url: str = PG_URL,
        timeout: float = 3.0,
        max_attempts: int = 3,
        backoff: float = 0.2,
    ) -> None:
        self.url = url
        self.timeout = timeout
        self.max_attempts = max_attempts
        self.backoff = backoff

    def approve(self, order_id: int, amount: int) -> dict:
        body = json.dumps({"order_id": order_id, "amount": amount}).encode()
        # 타임아웃 뒤 재시도해도 PG가 같은 요청으로 알아보도록 주문마다 고정된 키를 보낸다.
        request = urllib.request.Request(
            self.url,
            data=body,
            headers={
                "Content-Type": "application/json",
                "Idempotency-Key": f"approve-{order_id}",
            },
        )
        for attempt in range(1, self.max_attempts + 1):
            try:
                with urllib.request.urlopen(request, timeout=self.timeout) as response:
                    return json.loads(response.read())
            except OSError as e:
                if attempt == self.max_attempts or not self._retryable(e):
                    raise PgError(str(e)) from e
                # 지수 백오프에 지터를 더해 서버 3대가 동시에 재시도하지 않게 한다.
