from shop.db import Database

# 서버 3대가 각자 캐시를 가지므로 invalidate()는 해당 서버에만 적용된다.
# 다른 서버에는 TTL 안에 반영된다(최종적 일관성).
DETAIL_CACHE_TTL_SECONDS = 60


class ProductNotFound(Exception):
    pass


class ProductService:
    def __init__(
        self,
        database: Database,
        cache_ttl: float = DETAIL_CACHE_TTL_SECONDS,
        clock: Callable[[], float] = time.monotonic,
    ) -> None:
        self.db = database
        self._cache_ttl = cache_ttl
        self._clock = clock
        self._cache: dict[int, tuple[float, dict]] = {}
        self._lock = threading.Lock()

    def create_product(self, name: str, price: int, stock: int, description: str = "") -> dict:
        return self.db.products.insert(
            {"name": name, "price": price, "stock": stock, "description": description}
        )

    def get_product(self, product_id: int) -> dict:
        """상세 조회용. 최대 TTL만큼 오래된 값을 줄 수 있다. 금액 계산에는 get_product_fresh를 쓴다."""
        now = self._clock()
        with self._lock:
            hit = self._cache.get(product_id)
        if hit is not None and hit[0] > now:
            return dict(hit[1])
        product = self.get_product_fresh(product_id)
        with self._lock:
            self._cache[product_id] = (now + self._cache_ttl, dict(product))
        return product

    def get_product_fresh(self, product_id: int) -> dict:
        # 상세 화면마다 호출된다. 운영 DB에서는 상품·옵션·리뷰 요약을 조인해 느리다
        product = self.db.products.get(product_id)
        if product is None:
            raise ProductNotFound(product_id)
        return dict(product)

    def invalidate(self, product_id: int) -> None:
        """상품을 수정하는 코드는 커밋 후 이 서버의 캐시를 비우기 위해 호출한다."""
        with self._lock:
            self._cache.pop(product_id, None)

