class OutboxRelay:
    """outbox에 쌓인 이벤트를 알림 서비스로 보낸다.

    전달은 at-least-once다. 발송 직후 완료 표시 전에 서버가 죽으면 같은 이벤트가
    다시 가므로, 알림 서비스는 `event_id`로 중복을 걸러야 한다.
    서버 3대가 각자 돌려도 되도록 행을 집을 때 `locked_until`을 건다.
    운영(MySQL)에서는 이 선점을 `SELECT ... FOR UPDATE SKIP LOCKED`로 한다.
    """

    def __init__(self, database: Database, client: NotificationClient) -> None:
        self.db = database
        self.client = client

    def run_once(self, now: datetime | None = None) -> int:
        """발송 대상을 한 번 처리하고 성공한 건수를 돌려준다."""
        now = now or datetime.now(UTC)
        sent = 0
        for row in self._claim(now):
            try:
                self.client.send(
                    {"event_id": row["event_id"], "type": row["type"], "payload": row["payload"]}
                )
            except NotificationError as e:
                self._fail(row["id"], str(e), now)
            else:
                self.db.outbox.update(row["id"], status="SENT", sent_at=now.isoformat())
                sent += 1
        return sent

    def _claim(self, now: datetime) -> list[dict]:
        with self.db.transaction():
            due = [
                r
                for r in self.db.outbox.all()
                if r["status"] == "PENDING"
                and r["next_attempt_at"] <= now.isoformat()
                and (r["locked_until"] is None or r["locked_until"] <= now.isoformat())
            ]
            locked_until = (now + timedelta(seconds=LOCK_SECONDS)).isoformat()
            return [dict(self.db.outbox.update(r["id"], locked_until=locked_until)) for r in due]

    def _fail(self, row_id: int, error: str, now: datetime) -> None:
        attempts = self.db.outbox.get(row_id)["attempts"] + 1
        backoff = min(BACKOFF_BASE_SECONDS**attempts, BACKOFF_MAX_SECONDS)
        self.db.outbox.update(
            row_id,
            attempts=attempts,
            last_error=error,
            locked_until=None,
            next_attempt_at=(now + timedelta(seconds=backoff)).isoformat(),
            # 지우지 않고 DEAD로 남겨 두어 알람을 걸고 수동으로 재처리할 수 있게 한다.
