def enqueue(database: Database, event_type: str, aggregate_id: int, payload: dict) -> dict:
    """비즈니스 변경과 같은 트랜잭션 안에서 호출한다."""
    return database.outbox.insert(
        {
            "event_type": event_type,
            "aggregate_id": aggregate_id,
            "payload": payload,
            "status": "PENDING",
            "attempts": 0,
            "locked_until": None,
            "created_at": _now().isoformat(),
        }
