class OutboxRelay:
    """PENDING 행을 알림 서비스로 발행한다. 서버 3대가 동시에 돌아도 안전하다.

    운영(MySQL)에서는 `_claim`을 `SELECT ... FOR UPDATE SKIP LOCKED`로 바꿔도 된다.
    임대(lease)가 만료되면 다른 서버가 이어받으므로, 발행 후 완료 표시 전에
    서버가 죽어도 이벤트는 유실되지 않고 중복 발행만 될 수 있다.
    """

    def __init__(
        self,
        database: Database,
        client: NotificationClient,
        batch_size: int = 100,
        lease: timedelta = timedelta(seconds=30),
        max_attempts: int = 10,
    ) -> None:
        self.db = database
        self.client = client
        self.batch_size = batch_size
        self.lease = lease
        self.max_attempts = max_attempts

    def _claim(self) -> list[dict]:
        now = _now()
        claimed = []
        for row in sorted(self.db.outbox.all(), key=lambda r: r["id"]):
            if row["status"] != "PENDING":
                continue
            if row["locked_until"] and datetime.fromisoformat(row["locked_until"]) > now:
                continue
            claimed.append(
                self.db.outbox.update(
                    row["id"], locked_until=(now + self.lease).isoformat()
                )
            )
            if len(claimed) >= self.batch_size:
                break
        return claimed

    def run_once(self) -> int:
        """한 번 폴링해 발행에 성공한 건수를 돌려준다. 주기 실행은 호출 측이 맡는다."""
        sent = 0
        for row in self._claim():
            event = {
                "event_id": row["id"],
                "type": row["event_type"],
                "aggregate_id": row["aggregate_id"],
                "payload": row["payload"],
                "created_at": row["created_at"],
            }
            try:
                self.client.publish(event)
            except PublishError:
                attempts = row["attempts"] + 1
                # 실패해도 버리지 않는다. 한도를 넘으면 FAILED로 남겨 사람이 확인한다.
                status = "FAILED" if attempts >= self.max_attempts else "PENDING"
                self.db.outbox.update(
                    row["id"], attempts=attempts, status=status, locked_until=None
                )
                continue
            self.db.outbox.update(row["id"], status="SENT", locked_until=None)
            sent += 1
        return sent

