import threading
import uuid
from datetime import UTC, datetime, timedelta

from shop.db import Database
from shop.notifications import NotificationClient, NotificationError

PENDING = "PENDING"
SENT = "SENT"
DEAD = "DEAD"  # 재시도 한도 초과. 삭제하지 않고 남겨 알람·수동 재처리 대상으로 둔다.

