        {
            "event_id": str(uuid.uuid4()),
            "type": event_type,
            "payload": payload,
            "status": PENDING,
            "attempts": 0,
            "next_attempt_at": _now().isoformat(),
            "created_at": _now().isoformat(),
        }
    )


class OutboxRelay:
    def __init__(self, database: Database, client: NotificationClient) -> None:
        self.db = database
        self.client = client

    def _due(self, limit: int) -> list[dict]:
        now = _now().isoformat()
        rows = [
            r for r in self.db.outbox.all()
            if r["status"] == PENDING and r["next_attempt_at"] <= now
        ]
        return sorted(rows, key=lambda r: r["id"])[:limit]

    def publish_pending(self, limit: int = 100) -> int:
        """보낼 때가 된 이벤트를 전송하고 성공 건수를 돌려준다."""
        sent = 0
        for row in self._due(limit):
            try:
                self.client.send(row["event_id"], row["type"], row["payload"])
            except NotificationError:
                attempts = row["attempts"] + 1
                if attempts >= MAX_ATTEMPTS:
                    self.db.outbox.update(row["id"], attempts=attempts, status=DEAD)
                else:
                    delay = min(2**attempts, MAX_BACKOFF_SECONDS)
                    retry_at = (_now() + timedelta(seconds=delay)).isoformat()
                    self.db.outbox.update(row["id"], attempts=attempts, next_attempt_at=retry_at)
            else:
                self.db.outbox.update(row["id"], status=SENT)
                sent += 1
        return sent

    def run(self, stop: threading.Event, interval: float = 2.0) -> None:
        while not stop.is_set():
            self.publish_pending()
            stop.wait(interval)

