            data=data,
            method=method,
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            return json.loads(resp.read() or b"{}")

    def create_index(self) -> None:
        self._request("PUT", self.index_name, self.SETTINGS)

    def index(self, product: dict) -> None:
        doc = {"name": product["name"], "description": product.get("description", "")}
        self._request("PUT", f"{self.index_name}/_doc/{product['id']}", doc)

    def delete(self, product_id: int) -> None:
        self._request("DELETE", f"{self.index_name}/_doc/{product_id}")

    def search(self, keyword: str, limit: int) -> list[int]:
