        self.fail = fail
        self.indexed: list[int] = []
        self.names: dict[int, str] = {}

    def index(self, product: dict) -> None:
        if self.fail:
            raise SearchError("down")
        self.indexed.append(product["id"])
        self.names[product["id"]] = product["name"]

    def search(self, keyword: str, limit: int) -> list[int]:
        if self.fail:
            raise SearchError("down")
        return [i for i, name in self.names.items() if keyword in name][:limit]


