import json
import urllib.request
from typing import Protocol


class SearchIndex(Protocol):
    def index(self, product: dict) -> None: ...

    def search(self, keyword: str, limit: int) -> list[int]: ...


def _ngrams(text: str, n: int = 2) -> set[str]:
    text = text.lower()
    return {text[i : i + n] for i in range(len(text) - n + 1)}


class InMemorySearchIndex:
    """2-gram 역색인. 부분 문자열 검색("키보" → "키보드")을 기존 LIKE와 같게 맞춘다."""

    def __init__(self) -> None:
        self._docs: dict[int, str] = {}
        self._grams: dict[str, set[int]] = {}

    def index(self, product: dict) -> None:
        pid = product["id"]
        for ids in self._grams.values():
            ids.discard(pid)
        text = f"{product['name']} {product.get('description', '')}".lower()
        self._docs[pid] = text
        for gram in _ngrams(text):
            self._grams.setdefault(gram, set()).add(pid)

    def search(self, keyword: str, limit: int) -> list[int]:
        keyword = keyword.lower()
        grams = _ngrams(keyword)
        if grams:
            candidates = set.intersection(*(self._grams.get(g, set()) for g in grams))
        else:  # 1글자 이하는 n-gram이 없어 전체를 훑는다
            candidates = set(self._docs)
        return sorted(pid for pid in candidates if keyword in self._docs[pid])[:limit]


